function startQuiz(mode){let pool=questions.filter(q=>q.kind!=='gap'&&(mode==='mock'||practiceUnit==='All topics'||q.unit===practiceUnit));if(mode==='weak')pool=pool.filter(q=>state.questions[q.id]&&!state.questions[q.id].lastCorrect);if(!pool.length){toast('No missed questions in that topic yet.');return}let picked;if(mode==='mock'){const form=$('#mockForm')?.value||'fresh';picked=selectMock(pool,units,form,state.recentExams);state=appendProgress('exam',form+'-'+Date.now(),{questions:picked.map(q=>q.id)});if(typeof requestSync==='function')requestSync();}else picked=shuffled(pool).slice(0,mode==='quick'?10:pool.length);quiz={mode,questions:picked,index:0,answers:{},submitted:false,started:Date.now(),timer:false};view='practice';render();scrollMain()}
