function renderQuiz(){clearInterval(quizInterval);if(quiz.submitted){renderResults();return}const q=quiz.questions[quiz.index],isMock=quiz.mode==='mock',answered=Object.keys(quiz.answers).length;$('#main').innerHTML=`<p class="eyebrow">${isMock?'56-QUESTION MOCK EXAM':quiz.mode==='weak'?'MISSED-QUESTION REVIEW':'QUICK PRACTICE'}</p><h1>${isMock?'Make it a dress rehearsal.':'One question at a time.'}</h1><div class="quiz-status"><span>Question ${quiz.index+1} / ${quiz.questions.length} · ${answered} answered</span><span id="quizTime">${isMock?'<button class="text-btn" id="enableTimer">Enable 50-minute timer</button>':'Feedback after each answer'}</span></div><progress value="${answered}" max="${quiz.questions.length}" style="max-width:none;width:100%" aria-label="Questions answered"></progress><p class="subtle" style="margin-top:16px">${esc(q.unit)}</p>${questionHTML(q)}<div class="actions"><button class="btn secondary" id="quizPrev" ${quiz.index===0?'disabled':''}>Previous</button><button class="btn" id="quizNext" ${quiz.index===quiz.questions.length-1?'disabled':''}>Next question</button><button class="btn orange" id="submitQuiz" ${answered===quiz.questions.length?'':'disabled'}>Submit answers</button><button class="text-btn" id="leaveQuiz">Exit session</button></div>${isMock?`<div class="quiz-jump" aria-label="Jump to question">${quiz.questions.map((q,i)=>`<button data-jump="${i}" class="${quiz.answers[q.id]!==undefined?'done':''} ${i===quiz.index?'current':''}" aria-label="Question ${i+1}${quiz.answers[q.id]!==undefined?', answered':''}">${i+1}</button>`).join('')}</div>`:''}<p class="subtle">${isMock?'No correctness feedback until submission. You can change answers before submitting.':'Your first choice in this session is recorded. Review its explanation before moving on.'}</p>`;const container=$(`[data-q="${q.id}"]`),opts=questionOrder.get(q.id);
if(isMock){container.querySelectorAll('[data-answer]').forEach(btn=>{btn.classList.toggle('picked',quiz.answers[q.id]===+btn.dataset.answer);btn.setAttribute('aria-pressed',String(quiz.answers[q.id]===+btn.dataset.answer));btn.onclick=()=>{quiz.answers[q.id]=+btn.dataset.answer;renderQuiz()}})}else{if(quiz.answers[q.id]!==undefined){const pick=quiz.answers[q.id];container.dataset.answered='yes';container.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(opts[+b.dataset.answer].correct)b.classList.add('correct');else if(+b.dataset.answer===pick)b.classList.add('wrong')});const fb=container.querySelector('.feedback');fb.hidden=false;fb.classList.toggle('bad',!opts[pick].correct);fb.innerHTML=feedbackHTML(q,opts[pick])}else wireQuestion(container,q,(correct,pick)=>{quiz.answers[q.id]=pick;const y=window.scrollY;renderQuiz();window.scrollTo({top:y,behavior:'instant'});});}
$('#quizPrev').onclick=()=>{quiz.index--;renderQuiz();showQuizQuestion()};$('#quizNext').onclick=()=>{quiz.index++;renderQuiz();showQuizQuestion()};$('#submitQuiz').onclick=()=>{if(Object.keys(quiz.answers).length!==quiz.questions.length)return;if(isMock)quiz.questions.forEach(q=>record(q,questionOrder.get(q.id)[quiz.answers[q.id]].correct));quiz.submitted=true;renderQuiz();scrollMain()};$('#leaveQuiz').onclick=()=>{if(!confirm('Exit this session? Submitted practice answers stay saved; unfinished mock answers will be discarded.'))return;quiz=null;clearInterval(quizInterval);renderPractice()};document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{quiz.index=+b.dataset.jump;renderQuiz();showQuizQuestion()});if(isMock){if(quiz.timer)startTimer();else $('#enableTimer').onclick=()=>{quiz.timer=true;quiz.timerStart=Date.now();startTimer()}}}
function startTimer(){clearInterval(quizInterval);function tick(){if(!quiz||quiz.submitted)return;const remaining=Math.max(0,3000-Math.floor((Date.now()-quiz.timerStart)/1000));$('#quizTime').textContent=remaining?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} practice time left`:'Practice time elapsed · you can still finish';}tick();quizInterval=setInterval(tick,1000)}
function renderResults(){const right=quiz.questions.filter(q=>questionOrder.get(q.id)[quiz.answers[q.id]].correct),wrong=quiz.questions.filter(q=>!questionOrder.get(q.id)[quiz.answers[q.id]].correct),pct=Math.round(100*right.length/quiz.questions.length);$('#main').innerHTML=`<p class="eyebrow">FEEDBACK IS THE STUDY TOOL</p><h1>${right.length} / ${quiz.questions.length} correct.</h1><div class="grid"><div class="stat"><b>${pct}%</b>on this practice session</div><div class="stat"><b>${wrong.length}</b>questions to revisit</div></div><p class="subtle" style="margin-top:20px">This is a practice result, not a prediction of your exam grade. Video transcripts remain unavailable; topic allocation is a study choice.</p><div class="panel"><h2>By topic</h2>${units.filter(u=>quiz.questions.some(q=>q.unit===u)).map(u=>{const qs=quiz.questions.filter(q=>q.unit===u);const n=right.filter(q=>q.unit===u).length;return `<p>${esc(u)} <strong>${n} / ${qs.length}</strong></p>`}).join('')}</div><div class="actions"><button class="btn" id="finishQuiz">Back to practice</button>${wrong.length?'<button class="btn orange" id="retryWrong">Retry these misses</button>':''}</div><h2>Answer review</h2><div class="result-list">${[...wrong,...right].map(q=>{const opts=questionOrder.get(q.id),correct=opts.find(x=>x.correct),chosen=opts[quiz.answers[q.id]],ok=chosen.correct;return `<details ${!ok?'open':''}><summary><span class="${ok?'good-text':'bad-text'}">${ok?'✓':'✕'}</span> ${esc(q.prompt)}</summary><p>Your answer: <strong>${esc(chosen.label)}</strong><br>Correct: <strong>${esc(correct.label)}</strong></p>${feedbackHTML(q,chosen)}</details>`}).join('')}</div>`;$('#finishQuiz').onclick=()=>{quiz=null;renderPractice()};if(wrong.length)$('#retryWrong').onclick=()=>{quiz={mode:'weak',questions:shuffled(wrong),index:0,answers:{},submitted:false,started:Date.now(),timer:false};renderQuiz();scrollMain()}}
function renderCoverage(){const counts=units.map(u=>({unit:u,lessons:lessons.filter(l=>l.unit===u)}));$('#main').innerHTML=`<p class="eyebrow">SOURCE-GROUNDED COVERAGE / UPDATED ${esc(CONTENT.update.date)}</p><h1>Your complete study path.</h1><p>Your review sheet sets the scope: Chapters 2, 4, 5 and 6, Pearson (2010), lecture examples and assigned videos.</p><div class="grid"><div class="stat"><b>${lessons.length}</b>short lessons with recall + application</div><div class="stat"><b>${questions.length}</b>practice questions with explanations</div><div class="stat"><b>${cards.length}</b>spaced-recall flashcards</div></div><div class="panel"><h2>New material is integrated</h2><p>The supplied textbook notes and full Pearson article are now incorporated into lessons, cards and practice. The 56-question mock includes two Pearson questions. Your previous progress remains available in this browser.</p><button class="btn secondary" data-view="reference">Search all textbook sections</button></div><div class="notice"><strong>Remaining source limitation:</strong> ${esc(CONTENT.update.remaining[0])} The textbook coverage is based on your supplied structured notes; original illustrations are not reproduced beyond the existing lecture diagrams.</div><div class="grid"><div class="panel"><h2>Sources included</h2><p class="subtle">Research Methods I & II; Brain and Behavior I, II & III; Sensation and Perception; Consciousness; Exam 1 Review; Exam General Information and Study Tips.</p><p class="subtle">${esc(CONTENT.textbook.title)} by ${esc(CONTENT.textbook.authors)}: supplied notes for Chapters 2, 4, 5 and 6. Pearson (2010): full paper, methods, measures and findings.</p><p class="subtle">Every lesson identifies its source. Original slide diagrams remain in the relevant lessons.</p></div><div class="panel"><h2>Outside Exam 1 scope</h2><p class="subtle">Chapter 1; Chapter 3 sections 3-4 and 3-5; Chapter 7 (Emotion and Motivation). Signal detection, psychophysics and developmental changes in sensory modalities are excluded, as instructed. Sleep development is retained.</p><p class="subtle">The review sheet’s sample questions are not exhaustive.</p></div></div><div class="panel"><h2>How to study</h2><p>Try 20–30-minute sessions: 2–3 lessons → explain flashcards aloud → 10 questions → repair misses. Later, run the 56-question mock and revisit errors after a break.</p><p class="subtle">Prioritize lecture/text overlap, then lecture-only detail, then text-only essentials. Mock allocation (16 research, 24 brain, 8 sensation, 8 consciousness) is a study choice, not an instructor blueprint. Use topic practice to give text-only concepts extra attention.</p></div><details class="panel"><summary>Textbook and lecture wording to keep straight</summary>${CONTENT.update.clarifications.map(t=>`<p>${esc(t)}</p>`).join('')}</details><div class="panel"><h2>Study without a connection</h2><p>The downloaded offline version includes lessons, all questions and mock forms, flashcards, diagrams, labs and textbook notes. Export and import move progress between offline copies. Sign-in, cloud syncing, assigned videos and external source links require internet. Reconnect the live site to sync saved device changes.</p></div><h2>Every topic in the path</h2>${counts.map(({unit,lessons:ls})=>`<div class="coverage-heading"><h3>${esc(unit)}</h3><span class="badge">${ls.length} lessons</span></div><div class="map-list">${ls.map(l=>`<div class="map-item"><div><span class="title">${esc(l.title)}</span><p class="subtle">${esc(l.source)}</p></div><button class="btn secondary" data-lesson="${l.id}">${state.completed.includes(l.id)?'Revisit':'Study'}</button></div>`).join('')}</div>`).join('')}<div class="coverage-heading"><h2>Course videos & checkpoints</h2><span class="badge">${state.videos.length} / ${CONTENT.videos.length} reviewed</span></div><p class="subtle">Open the assigned video, then answer the checkpoint from memory. Some clips may require UW access. Full transcripts were not supplied or retrievable; these checkpoints follow slide prompts and identified background.</p>${CONTENT.videos.map((v,i)=>`<section class="video-item"><span class="eyebrow">${esc(v.unit)}</span><h3><a href="${esc(v.url)}" target="_blank" rel="noopener">${esc(v.title)} · Watch assigned clip</a></h3><p>${esc(v.prompt)}</p><details><summary>Show checkpoint guidance</summary><p>${esc(v.answer)}</p></details><div class="actions"><button class="btn secondary" data-video="${i}">${state.videos.includes(i)?'Reviewed ✓':'Mark video reviewed'}</button></div></section>`).join('')}<details class="panel"><summary>Additional background sources from the original version</summary><p class="subtle">These were used for supplemental background before the textbook notes arrived. Their chapter numbers can differ from your assigned book.</p>${CONTENT.references.map(r=>`<p class="subtle"><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a></p>`).join('')}</details>`;document.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>{const i=+b.dataset.video;if(state.videos.includes(i))state.videos=state.videos.filter(x=>x!==i);else state.videos.push(i);save();b.textContent=state.videos.includes(i)?'Reviewed ✓':'Mark video reviewed'})}

// Render only the uploaded notes' simple Markdown constructs, escaping all source text.
function noteInline(text){return esc(text).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/`(.+?)`/g,'<code>$1</code>')}
function noteMarkdown(text){const lines=text.split('\n'),out=[];let i=0;while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue}if(line.startsWith('|')){const rows=[];while(i<lines.length&&lines[i].startsWith('|')){const cells=lines[i].split('|').slice(1,-1).map(t=>t.trim());if(!cells.every(t=>/^:?-+:?$/.test(t)))rows.push(cells);i++}out.push('<div class="table-scroll"><table><thead><tr>'+rows[0].map(t=>'<th scope="col">'+noteInline(t)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(1).map(row=>'<tr>'+row.map(t=>'<td>'+noteInline(t)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue}if(/^[-*] /.test(line)){const items=[];while(i<lines.length&&/^[-*] /.test(lines[i])){items.push('<li>'+noteInline(lines[i].slice(2))+'</li>');i++}out.push('<ul>'+items.join('')+'</ul>');continue}const paragraph=[];while(i<lines.length&&lines[i].trim()&&!lines[i].startsWith('|')&&!/^[-*] /.test(lines[i]))paragraph.push(lines[i++]);out.push('<p>'+noteInline(paragraph.join(' '))+'</p>')}return out.join('')}
let referenceChapter='All chapters',referenceSearch='';
function renderReference(){const chapters=CONTENT.textbook.chapters;$('#main').innerHTML=`<p class="eyebrow">ASSIGNED TEXTBOOK / DEEP REFERENCE</p><h1>Find the detail you need.</h1><p>Use the short lessons for active study. Search these supplied notes for textbook examples, tables, figure explanations and finer distinctions.</p><p class="subtle">${esc(CONTENT.textbook.title)} · ${esc(CONTENT.textbook.authors)}. ${esc(CONTENT.textbook.provenance)}</p><div class="select-row"><label>Chapter<select id="referenceChapter"><option>All chapters</option>${chapters.map(ch=>`<option ${ch.title===referenceChapter?'selected':''}>${esc(ch.title)}</option>`).join('')}</select></label><label class="reference-search">Search all notes<input type="search" id="referenceSearch" placeholder="Try: ghrelin, Capgras, zero-sum…" value="${esc(referenceSearch)}"></label></div><p id="referenceCount" class="subtle" role="status"></p><div id="referenceResults"></div>`;$('#referenceChapter').onchange=e=>{referenceChapter=e.target.value;updateReference()};$('#referenceSearch').oninput=e=>{referenceSearch=e.target.value;updateReference()};updateReference()}
function updateReference(){const query=referenceSearch.trim().toLowerCase(),chapters=CONTENT.textbook.chapters.filter(ch=>referenceChapter==='All chapters'||ch.title===referenceChapter);let n=0;$('#referenceResults').innerHTML=chapters.map(ch=>{const sections=ch.sections.filter(s=>!query||(s.title+' '+s.text).toLowerCase().includes(query));n+=sections.length;return sections.length?`<h2>${esc(ch.title)}</h2>${sections.map(s=>`<details class="reference-section" ${query?'open':''}><summary>${esc(s.title)}</summary><div class="reference-body">${noteMarkdown(s.text)}</div></details>`).join('')}`:''}).join('');$('#referenceCount').textContent=n+' matching section'+(n===1?'':'s');if(!n)$('#referenceResults').innerHTML='<div class="empty"><p>No matching notes. Try a shorter term or another chapter.</p></div>'}

function renderLabs(){stopStroop();$('#main').innerHTML=`<p class="eyebrow">PLAY WITH THE CONCEPT</p><h1>Make the idea concrete.</h1><p>Change one thing, predict the result, then explain why it happened.</p><div class="lab-tabs">${[['correlation','Correlation sandbox'],['stroop','Stroop challenge'],['split','Split-brain predictions']].map(([id,label])=>`<button class="btn secondary ${lab===id?'active':''}" data-lab="${id}">${label}</button>`).join('')}</div><div id="labView" class="lab-view"></div>`;document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{lab=b.dataset.lab;renderLabs()});({correlation:correlationLab,stroop:stroopLab,split:splitLab})[lab]()}
function correlationLab(){$('#labView').innerHTML=`<section class="panel"><h2>Direction is not strength.</h2><p>Move r from −1 to +1. A tight downward pattern is strong, even though its sign is negative.</p><label for="corrRange">Correlation: <strong id="corrLabel">+0.65</strong></label><input class="range" id="corrRange" type="range" min="-1" max="1" step="0.05" value="0.65"><canvas id="scatter" width="760" height="430" aria-label="Interactive scatterplot of two synthetic variables"></canvas><p class="lab-note subtle" id="corrNote"></p><div class="notice">These are synthetic data. Moving this control changes a relationship, but a scatterplot alone still cannot tell you what caused it.</div><button class="btn secondary" data-lesson="correlation">Review correlation lesson</button></section>`;$('#corrRange').oninput=drawCorrelation;drawCorrelation()}
function drawCorrelation(){const r=+$('#corrRange').value,n=42,x=Array.from({length:n},(_,i)=>(i-(n-1)/2)/12);let z=Array.from({length:n},(_,i)=>Math.sin(i*2.399)+.5*Math.cos(i*1.721));const zm=z.reduce((a,b)=>a+b,0)/n;z=z.map(v=>v-zm);const proj=z.reduce((s,v,i)=>s+v*x[i],0)/x.reduce((s,v)=>s+v*v,0);z=z.map((v,i)=>v-proj*x[i]);const scale=Math.sqrt(x.reduce((s,v)=>s+v*v,0)/z.reduce((s,v)=>s+v*v,0));z=z.map(v=>v*scale);const y=x.map((v,i)=>r*v+Math.sqrt(Math.max(0,1-r*r))*z[i]);const canvas=$('#scatter'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p=55,max=3;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#e4edef';ctx.lineWidth=1;for(let i=0;i<=6;i++){let xx=p+i*(w-p*2)/6,yy=p+i*(h-p*2)/6;ctx.beginPath();ctx.moveTo(xx,p);ctx.lineTo(xx,h-p);ctx.stroke();ctx.beginPath();ctx.moveTo(p,yy);ctx.lineTo(w-p,yy);ctx.stroke()}ctx.strokeStyle='#45656f';ctx.beginPath();ctx.moveTo(p,p);ctx.lineTo(p,h-p);ctx.lineTo(w-p,h-p);ctx.stroke();ctx.fillStyle='#087963';x.forEach((v,i)=>{ctx.beginPath();ctx.arc(p+(v+max)/(2*max)*(w-2*p),h-p-(y[i]+max)/(2*max)*(h-2*p),5,0,Math.PI*2);ctx.fill()});ctx.font='16px system-ui';ctx.fillStyle='#122b36';ctx.fillText('Variable A',w/2-35,h-16);ctx.save();ctx.translate(20,h/2+35);ctx.rotate(-Math.PI/2);ctx.fillText('Variable B',0,0);ctx.restore();$('#corrLabel').textContent=(r>=0?'+':'')+r.toFixed(2);$('#corrNote').textContent=r===0?'r = 0: no linear relationship in these data. A nonlinear relationship could still exist in other datasets.':`${r>0?'Positive':'Negative'} direction; ${Math.abs(r)>=.7?'strong':Math.abs(r)>=.3?'moderate':'weak'} linear relationship. Strength labels are illustrative, not universal cutoffs. Absolute magnitude: ${Math.abs(r).toFixed(2)}.`}
function stopStroop(){if(stroopTimer)clearTimeout(stroopTimer);stroopTimer=null}
const colorNames=['RED','BLUE','GREEN','PURPLE'];const colorHex=['#bd263d','#215ecd','#08744c','#7d36b5'];
function stroopLab(){stroop=null;$('#labView').innerHTML=`<section class="panel"><h2>Read the ink. Ignore the word.</h2><p>Answer 16 trials: half matching, half conflicting. The summary compares your response time and errors. Use buttons or keys 1–4.</p><div class="notice">This is a learning demo, not a psychological assessment. A small run can be noisy; practice and order affect times.</div><button class="btn" id="startStroop">Start 16 trials</button><div id="stroopArea"></div></section>`;$('#startStroop').onclick=()=>{const trials=shuffled(Array.from({length:16},(_,i)=>{const ink=i%4;return {ink,word:i<8?ink:(ink+1+Math.floor(Math.random()*3))%4,congruent:i<8}}));stroop={trials,index:0,results:[],ready:false};$('#startStroop').hidden=true;showStroopTrial()}}
function showStroopTrial(){if(!stroop)return;const t=stroop.trials[stroop.index];if(!t){const summary=kind=>{const rs=stroop.results.filter(r=>r.congruent===kind),good=rs.filter(r=>r.correct);return {errors:rs.length-good.length,time:good.length?Math.round(good.reduce((a,r)=>a+r.ms,0)/good.length):null}};const c=summary(true),i=summary(false);$('#stroopArea').innerHTML=`<div class="grid" style="margin-top:25px"><div class="stat"><h3>Matching</h3><b>${c.time===null?'—':c.time+' ms'}</b>${c.errors} / 8 errors</div><div class="stat"><h3>Conflicting</h3><b>${i.time===null?'—':i.time+' ms'}</b>${i.errors} / 8 errors</div></div><p style="margin-top:20px">Times average correct responses only. ${c.time!==null&&i.time!==null?`Your conflicting trials were ${Math.abs(i.time-c.time)} ms ${i.time>=c.time?'slower':'faster'}.`:''} In the usual Stroop effect, conflict slows color naming because automatic reading interferes. One small run may differ.</p><div class="actions"><button class="btn" id="restartStroop">Try again</button><button class="btn secondary" data-lesson="attention">Review attention</button></div>`;$('#restartStroop').onclick=stroopLab;stroop.ready=false;return}$('#stroopArea').innerHTML=`<p class="subtle" style="margin-top:20px">Trial ${stroop.index+1} / 16 · name the ink color</p><div class="stroop-word" style="color:${colorHex[t.ink]}">${colorNames[t.word]}</div><div class="stroop-choices">${colorNames.map((name,i)=>`<button data-color="${i}">${i+1} · ${name.toLowerCase()}</button>`).join('')}</div>`;stroop.ready=true;stroop.start=performance.now();document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>answerStroop(+b.dataset.color))}
function answerStroop(i){if(!stroop?.ready||view!=='labs'||lab!=='stroop')return;const t=stroop.trials[stroop.index];stroop.ready=false;stroop.results.push({congruent:t.congruent,correct:i===t.ink,ms:performance.now()-stroop.start});stroop.index++;document.querySelectorAll('[data-color]').forEach(b=>b.disabled=true);stroopTimer=setTimeout(showStroopTrial,250)}
function splitLab(){const left=splitField==='left';$('#labView').innerHTML=`<section class="panel"><h2>Which hemisphere knows?</h2><p>A split-brain patient fixates centrally. A key flashes briefly in one visual field. Assume the usual left-hemisphere language dominance.</p><div class="select-row"><label>Stimulus position<select id="splitField"><option value="left" ${left?'selected':''}>Left visual field</option><option value="right" ${!left?'selected':''}>Right visual field</option></select></label></div><div class="route-diagram"><div>${left?'Left':'Right'} visual field<small>Not the same as one eye</small></div><div>Which hemisphere?<small>Predict before revealing</small></div><div>Speech & hand?<small>Predict what the patient can do</small></div></div><p><strong>Which prediction is best?</strong></p><div class="choices"><button class="choice" id="splitA">Cannot name it, but can pick it with the left hand</button><button class="choice" id="splitB">Can usually name it and pick it with the right hand</button></div><div class="feedback" id="splitFeedback" hidden></div><div class="actions"><button class="btn secondary" data-lesson="split">Review split-brain lesson</button></div></section>`;$('#splitField').onchange=e=>{splitField=e.target.value;splitLab()};function answer(pickLeft){const ok=left===pickLeft;$('#splitFeedback').hidden=false;$('#splitFeedback').classList.toggle('bad',!ok);$('#splitFeedback').innerHTML=`<strong>${ok?'Correct.':'Follow the crossing.'}</strong> ${left?'Left field → right hemisphere. Without the corpus callosum, the information cannot reach typical left-language systems. The left hand can select the key.':'Right field → left hemisphere. This hemisphere supports typical language and right-hand control, so naming and right-hand selection are possible.'}`;$('#splitA').disabled=true;$('#splitB').disabled=true;}$('#splitA').onclick=()=>answer(true);$('#splitB').onclick=()=>answer(false)}
// Event delegation keeps lesson and mode links consistent across views.
document.addEventListener('click',e=>{const b=e.target.closest('[data-lesson],[data-view]');if(!b)return;if(b.dataset.lesson)openLesson(b.dataset.lesson);else setView(b.dataset.view)});
document.addEventListener('keydown',e=>{if(view==='labs'&&lab==='stroop'&&stroop?.ready&&/^[1-4]$/.test(e.key)&&!e.repeat&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();answerStroop(+e.key-1)}});
$('#resume').onclick=()=>{if(selectedExamId==='exam2'){Exam2Study.resume();return;}const l=lessons.find(x=>!state.completed.includes(x.id));openLesson(l?.id||state.lastLesson)};
function downloadJSON(data,name){
  const text=typeof data==='string'?data:JSON.stringify(data,null,2),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),dialog=document.createElement('dialog');
  dialog.className='export-dialog';dialog.innerHTML='<h2>Progress recovery copy.</h2><p>Your JSON export is ready. If the download does not open in this browser, select and copy the JSON below into a file ending in .json. Import that file to merge or restore progress.</p><a class="btn" id="downloadProgressJSON">Download JSON</a><label>Progress JSON<textarea id="progressExportText" readonly spellcheck="false"></textarea></label><div class="actions"><button class="btn secondary" id="selectProgressJSON">Select JSON</button><button class="btn" id="closeProgressExport">Close</button></div>';
  const a=dialog.querySelector('a'),area=dialog.querySelector('textarea');a.href=url;a.download=name;area.value=text;document.body.append(dialog);dialog.showModal();
  dialog.querySelector('#selectProgressJSON').onclick=()=>{area.focus();area.select();};dialog.querySelector('#closeProgressExport').onclick=()=>dialog.close();dialog.onclose=()=>{URL.revokeObjectURL(url);dialog.remove();};a.click();
}
$('#export').onclick=()=>{if(selectedExamId==='exam2'){downloadJSON(Exam2Store.exportFile(),'psych-202-exam2-progress.json');return;}if(selectedExamId!=='exam1'){toast('No progress yet for this exam.');return;}downloadJSON({version:2,examId:'exam1',events:progressEvents,...StudyProgress.materialize(progressEvents)},'psych-202-exam1-progress.json');};
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>30000000)throw Error('File is too large');const raw=await file.text(),data=JSON.parse(raw);if(selectedExamId==='exam2'){Exam2Store.importFile(data);Exam2Study.resetSession();render();if(typeof requestSync==='function')requestSync();toast('Exam 2 progress merged.');return;}if(selectedExamId!=='exam1')throw Error('Select the exam this export belongs to before importing.');state=mergeProgressExport(data,raw);lessonId=lessons.some(l=>l.id===state.lastLesson)?state.lastLesson:lessons[0].id;quiz=null;cardDeck=[];cardIndex=0;render();if(typeof requestSync==='function')requestSync();toast('Progress merged. An untouched pre-import copy was saved.');}catch(err){toast('Could not import: '+err.message);}finally{e.target.value='';}};
$('#backup').onclick=()=>{if(selectedExamId!=='exam1'){toast('The original backup is for Exam 1. Use Export progress for the selected exam.');return;}const owner=localStorage.getItem(PROGRESS_PREFIX+'guest-owner');if(progressScope.startsWith('account:')&&owner&&progressScope!=='account:'+owner){toast('Use Export progress to back up this account. The original device backup belongs to its first account.');return;}const raw=localStorage.getItem(BACKUP_KEY);if(raw)downloadJSON(raw,'psych-202-original-progress-backup.json');else toast('No version-1 backup exists in this browser. Export current progress to keep a recovery copy.');};
function showQuizQuestion(){document.querySelector('.question')?.scrollIntoView({block:'start',behavior:'instant'});}
function feedbackHTML(q,chosen){const l=lessons.find(l=>l.id===q.lessonId),why=q.choiceExplanations?.[chosen.original],references=[...new Set([q.source||l.source,...(q.supportingSources||[])])].join('; ');return '<strong>'+(chosen.correct?'Correct.':'Let’s repair this.')+'</strong><p><b>Why the correct answer is right:</b> '+esc(q.explanation)+'</p>'+(!chosen.correct?'<p><b>Why your answer is wrong:</b> '+esc(why||('The selected answer, “'+chosen.label+'”, does not fit this question. '+q.explanation))+'</p><p><b>Misconception to check:</b> '+esc(q.misconception||'Separate the roles and evidence described in this lesson; a related concept does not necessarily answer this particular question.')+'</p>':'')+'<p class="subtle">Source: '+esc(references)+'</p><button class="text-btn" data-lesson="'+q.lessonId+'">Revisit '+esc(l.title)+'</button>';}
function addQuestionRetry(container,q){const b=document.createElement('button');b.type='button';b.className='btn secondary question-retry';b.textContent='Retry question';container.querySelector('.feedback').append(b);b.onclick=()=>{delete container.dataset.answered;container.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=false;x.classList.remove('correct','wrong');});container.querySelector('.feedback').hidden=true;container.querySelector('[data-answer]').focus({preventScroll:true});};}
function registerStudyTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifetime=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifetime.signal})).catch(()=>{})}catch(e){}};register({name:'read_study_progress',description:'Read lesson review counts and question accuracy for this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>selectedExamId==='exam2'?Exam2Study.metrics():({exam:ExamSpaces.get(selectedExamId).label,completedLessons:selectedExamId==='exam1'?state.completed.filter(id=>lessons.some(l=>l.id===id)).length:0,totalLessons:selectedExamId==='exam1'?lessons.length:0,missedQuestions:selectedExamId==='exam1'?questions.filter(q=>state.questions[q.id]&&!state.questions[q.id].lastCorrect).length:0,missingSources:selectedExamId==='exam1'?CONTENT.update.remaining:[]})});register({name:'open_study_lesson',description:'Open an Exam 1 lesson by ID, switching to Exam 1; does not mark it reviewed.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.lessonId!=='string'||!lessons.some(l=>l.id===input.lessonId))throw Error('Unknown lesson');openLesson(input.lessonId);return {opened:input.lessonId,title:lessons.find(l=>l.id===input.lessonId).title}}});window.addEventListener('pagehide',()=>lifetime.abort(),{once:true})}
render();registerStudyTools();if(!storageOK)toast('Browser saving is unavailable. Export progress before leaving.');
